#!/usr/bin/env node
/**
 * 18 Nov 2026: copies the nine per-language rule files from
 * docs/engineering/language-blocks/ into src/lib/will/language-rules.generated.ts,
 * so the deployed app can load them without reading the file system.
 *
 * Run after any change to a rule file:  node scripts/build-language-rules.mjs
 * The generated file is checked in. Do not edit it by hand.
 */
import { readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const LANGS = ['en', 'de', 'es', 'fr', 'it', 'pt', 'ja', 'zh', 'vi'];

const entries = LANGS.map((lang) => {
  const text = readFileSync(join(root, 'docs/engineering/language-blocks', `${lang}.md`), 'utf8');
  return `  ${JSON.stringify(lang)}: ${JSON.stringify(text)},`;
});

const out = `/* GENERATED by scripts/build-language-rules.mjs from docs/engineering/language-blocks/. Do not edit. */
export const LANGUAGE_RULES: Record<string, string> = {
${entries.join('\n')}
};
`;

writeFileSync(join(root, 'src/lib/will/language-rules.generated.ts'), out);
console.log(`wrote ${LANGS.length} language rule files`);
